// ============================================================
// Service Worker — To-Do List (Background & Push Notifications)
// ============================================================

export function renderServiceWorker(): string {
  return /*javascript*/ `
const CACHE_NAME = 'todolist-v2';
const STATIC_ASSETS = [
  '/',
  '/manifest.json',
  '/icon-192.png'
];

// Cài đặt Service Worker
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(STATIC_ASSETS))
  );
  self.skipWaiting();
});

// Kích hoạt Service Worker
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => {
      return Promise.all(
        keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))
      );
    })
  );
  self.clients.claim();
});

// Lắng nghe sự kiện Fetch (hỗ trợ offline nhẹ)
self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;
  const url = new URL(event.request.url);
  if (url.pathname.startsWith('/api/')) return; // Không cache API

  event.respondWith(
    caches.match(event.request).then((cached) => {
      return cached || fetch(event.request).catch(() => caches.match('/'));
    })
  );
});

// ─── HIỂN THỊ THÔNG BÁO TỪ TRANG WEB QUA SERVICE WORKER ───
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SHOW_NOTIFICATION') {
    const { title, body, tag } = event.data;
    self.registration.showNotification(title || 'To-Do List', {
      body: body || 'Bạn có công việc cần hoàn thành!',
      icon: '/icon-192.png',
      badge: '/icon-192.png',
      tag: tag || 'todo-reminder',
      renotify: true,
      vibrate: [200, 100, 200],
      data: { url: '/' }
    });
  }
});

// ─── LẮNG NGHE WEB PUSH NOTIFICATION KHI TẮT TRÌNH DUYỆT ───
self.addEventListener('push', (event) => {
  let data = {};
  if (event.data) {
    try {
      data = event.data.json();
    } catch {
      data = { title: 'To-Do List', body: event.data.text() };
    }
  }

  const title = data.title || 'To-Do List';
  const options = {
    body: data.body || 'Nhắc nhở công việc sắp đến hạn!',
    icon: '/icon-192.png',
    badge: '/icon-192.png',
    tag: data.tag || 'todo-push',
    renotify: true,
    vibrate: [200, 100, 200],
    data: { url: data.url || '/' }
  };

  event.waitUntil(self.registration.showNotification(title, options));
});

// ─── XỬ LÝ KHI NGƯỜI DÙNG BẤM VÀO THÔNG BÁO ───
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const targetUrl = (event.notification.data && event.notification.data.url) || '/';

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if (client.url.includes(targetUrl) && 'focus' in client) {
          return client.focus();
        }
      }
      if (clients.openWindow) {
        return clients.openWindow(targetUrl);
      }
    })
  );
});
`;
}
